   419  template <typename UINT>
   420  struct CmapSubtableTrimmed
   421  {
   422    inline bool get_glyph (hb_codepoint_t codepoint, hb_codepoint_t *glyph) const
   423    {
   424      /* Rely on our implicit array bound-checking. */
   425      hb_codepoint_t gid = glyphIdArray[codepoint - startCharCode];
   426      if (!gid)
   427        return false;
   428      *glyph = gid;
   429      return true;
   430    }
   431    inline void collect_unicodes (hb_set_t *out) const
   432    {
   433      hb_codepoint_t start = startCharCode;
   434      unsigned int count = glyphIdArray.len;
   435      for (unsigned int i = 0; i < count; i++)
   436        if (glyphIdArray[i])
   437          out->add (start + i);
   438    }
   439
   440    inline bool sanitize (hb_sanitize_context_t *c) const
   441    {
   442      TRACE_SANITIZE (this);
   443      return_trace (c->check_struct (this) && glyphIdArray.sanitize (c));
   444    }
   445
   446    protected:
   447    UINT          formatReserved; /* Subtable format and (maybe) padding. */
   448    UINT          length;         /* Byte length of this subtable. */
   449    UINT          language;       /* Ignore. */
   450    UINT          startCharCode;  /* First character code covered. */
   451    ArrayOf<GlyphID, UINT>
   452                  glyphIdArray;   /* Array of glyph index values for character
   453                                   * codes in the range. */
   454    public:
   455    DEFINE_SIZE_ARRAY (5 * sizeof (UINT), glyphIdArray);
   456  };
