   461  template <typename T>
   462  struct CmapSubtableLongSegmented
   463  {
   464    friend struct cmap;
   465
   466    inline bool get_glyph (hb_codepoint_t codepoint, hb_codepoint_t *glyph) const
   467    {
   468      int i = groups.bsearch (codepoint);
   469      if (i == -1)
   470        return false;
   471      hb_codepoint_t gid = T::group_get_glyph (groups[i], codepoint);
   472      if (!gid)
   473        return false;
   474      *glyph = gid;
   475      return true;
   476    }
   477
   478    inline void collect_unicodes (hb_set_t *out) const
   479    {
   480      for (unsigned int i = 0; i < this->groups.len; i++) {
   481        out->add_range (this->groups[i].startCharCode,
   482                        MIN ((hb_codepoint_t) this->groups[i].endCharCode,
   483                             (hb_codepoint_t) HB_UNICODE_MAX));
   484      }
   485    }
   486
   487    inline bool sanitize (hb_sanitize_context_t *c) const
   488    {
   489      TRACE_SANITIZE (this);
   490      return_trace (c->check_struct (this) && groups.sanitize (c));
   491    }
   492
   493    inline bool serialize (hb_serialize_context_t *c,
   494                           const hb_vector_t<CmapSubtableLongGroup> &group_data)
   495    {
   496      TRACE_SERIALIZE (this);
   497      if (unlikely (!c->extend_min (*this))) return_trace (false);
   498      Supplier<CmapSubtableLongGroup> supplier (group_data.arrayZ, group_data.len);
   499      if (unlikely (!groups.serialize (c, supplier, group_data.len))) return_trace (false);
   500      return true;
   600    inline int cmp (const hb_codepoint_t &codepoint) const
   601    {
   602      if (codepoint < startUnicodeValue) return -1;
   603      if (codepoint > startUnicodeValue + additionalCount) return +1;
   604      return 0;
   605    }
   606
   607    inline bool sanitize (hb_sanitize_context_t *c) const
   608    {
   609      TRACE_SANITIZE (this);
   610      return_trace (c->check_struct (this));
   611    }
   612
   613    HBUINT24      startUnicodeValue;      /* First value in this range. */
   614    HBUINT8       additionalCount;        /* Number of additional values in this
   615                                           * range. */
   616    public:
   617    DEFINE_SIZE_STATIC (4);
   618  };
