   620  struct DefaultUVS : SortedArrayOf<UnicodeValueRange, HBUINT32>
   621  {
   622    inline void collect_unicodes (hb_set_t *out) const
   623    {
   624      unsigned int count = len;
   625      for (unsigned int i = 0; i < count; i++)
   626      {
   627        hb_codepoint_t first = arrayZ[i].startUnicodeValue;
   628        hb_codepoint_t last = MIN ((hb_codepoint_t) (first + arrayZ[i].additionalCount),
   629                                   (hb_codepoint_t) HB_UNICODE_MAX);
   630        out->add_range (first, last);
   631      }
   632    }
   633
   634    public:
   635    DEFINE_SIZE_ARRAY (4, arrayZ);
   636  };
