   757  struct CmapSubtable
   758  {
   759    /* Note: We intentionally do NOT implement subtable formats 2 and 8. */
   760
   761    inline bool get_glyph (hb_codepoint_t codepoint,
   762                           hb_codepoint_t *glyph) const
   763    {
   764      switch (u.format) {
   765      case  0: return u.format0 .get_glyph (codepoint, glyph);
   766      case  4: return u.format4 .get_glyph (codepoint, glyph);
   767      case  6: return u.format6 .get_glyph (codepoint, glyph);
   768      case 10: return u.format10.get_glyph (codepoint, glyph);
   769      case 12: return u.format12.get_glyph (codepoint, glyph);
   770      case 13: return u.format13.get_glyph (codepoint, glyph);
   771      case 14:
   772      default: return false;
   773      }
   774    }
   775    inline void collect_unicodes (hb_set_t *out) const
   776    {
   777      switch (u.format) {
   778      case  0: u.format0 .collect_unicodes (out); return;
   779      case  4: u.format4 .collect_unicodes (out); return;
   780      case  6: u.format6 .collect_unicodes (out); return;
   781      case 10: u.format10.collect_unicodes (out); return;
   782      case 12: u.format12.collect_unicodes (out); return;
   783      case 13: u.format13.collect_unicodes (out); return;
   784      case 14:
   785      default: return;
   786      }
   787    }
   788
   789    inline bool sanitize (hb_sanitize_context_t *c) const
   790    {
   791      TRACE_SANITIZE (this);
   792      if (!u.format.sanitize (c)) return_trace (false);
   793      switch (u.format) {
   794      case  0: return_trace (u.format0 .sanitize (c));
   795      case  4: return_trace (u.format4 .sanitize (c));
   796      case  6: return_trace (u.format6 .sanitize (c));
   797      case 10: return_trace (u.format10.sanitize (c));
   798      case 12: return_trace (u.format12.sanitize (c));
   799      case 13: return_trace (u.format13.sanitize (c));
   800      case 14: return_trace (u.format14.sanitize (c));
   801      default:return_trace (true);
   802      }
   803    }
