   805    public:
  1080      inline bool get_variation_glyph (hb_codepoint_t  unicode,
  1081                                       hb_codepoint_t  variation_selector,
  1082                                       hb_codepoint_t *glyph) const
  1083      {
  1084        switch (this->subtable_uvs->get_glyph_variant (unicode,
  1085                                                       variation_selector,
  1086                                                       glyph))
  1087        {
  1088          case GLYPH_VARIANT_NOT_FOUND:   return false;
  1089          case GLYPH_VARIANT_FOUND:       return true;
  1090          case GLYPH_VARIANT_USE_DEFAULT: break;
  1091        }
  1092
  1093        return get_nominal_glyph (unicode, glyph);
  1094      }
  1095
  1096      inline void collect_unicodes (hb_set_t *out) const
  1097      {
  1098        subtable->collect_unicodes (out);
  1099      }
  1100      inline void collect_variation_selectors (hb_set_t *out) const
  1101      {
  1102        subtable_uvs->collect_variation_selectors (out);
  1103      }
  1104      inline void collect_variation_unicodes (hb_codepoint_t variation_selector,
  1105                                              hb_set_t *out) const
  1106      {
  1107        subtable_uvs->collect_variation_unicodes (variation_selector, out);
  1108      }
  1109
  1110      protected:
